#!/usr/bin/env python3
"""Apply the catalog tranche over the captured dirty Vapor Client source tree.

No Cargo, fmt, build, test, deploy, commit, reset, or account mutation is run.
Rust-token context guards ignore layout, preserve other changes, and reject ambiguity.
"""
import argparse, base64, difflib, gzip, json, os, re, stat, subprocess, sys, tempfile
from pathlib import Path

PAYLOAD = ""

def tokens(text, comments=False):
    result=[]; i=0
    while i<len(text):
        begin=i
        if text[i].isspace(): i+=1; continue
        if text.startswith('//',i):
            end=text.find('\n',i); i=len(text) if end<0 else end
            if comments: result.append((text[begin:i],begin,i))
            continue
        if text.startswith('/*',i):
            depth=1; i+=2
            while depth and i<len(text):
                if text.startswith('/*',i): depth+=1; i+=2
                elif text.startswith('*/',i): depth-=1; i+=2
                else:i+=1
            if depth: raise ValueError('Unterminated Rust block comment')
            if comments:result.append((text[begin:i],begin,i))
            continue
        raw=re.match(r'(?:br|r)(\#*)"',text[i:])
        if raw:
            closing='"'+raw.group(1); end=text.find(closing,i+raw.end())
            if end<0:raise ValueError('Unterminated Rust raw string')
            i=end+len(closing)
        elif text[i]=='"':
            i+=1
            while i<len(text):
                if text[i]=='\\':i+=2
                elif text[i]=='"':i+=1;break
                else:i+=1
        else:
            char=re.match(r"'(?:\\(?:u\{[0-9a-fA-F_]+\}|.)|[^'\\])'",text[i:])
            word=re.match(r'\w+',text[i:],re.UNICODE)
            if char:i+=char.end()
            elif word:i+=word.end()
            else:i+=1
        if not comments:result.append((text[begin:i],begin,i))
    return result

def values(text):return [x[0] for x in tokens(text)]
def matches(haystack,needle):
    if not needle:raise ValueError('Empty structural guard')
    return [i for i in range(len(haystack)-len(needle)+1) if haystack[i:i+len(needle)]==needle]

def patch_text(current,before,after):
    old=tokens(before); new=tokens(after); actual=tokens(current)
    actual_values=[t[0] for t in actual]; edits=[]
    diff=difflib.SequenceMatcher(a=[t[0] for t in old],b=[t[0] for t in new],autojunk=False)
    for group in diff.get_grouped_opcodes(128):
        a,b=group[0][1],group[-1][2]; c,d=group[0][3],group[-1][4]
        old_values=[t[0] for t in old[a:b]]; new_values=[t[0] for t in new[c:d]]
        found=matches(actual_values,old_values)
        if not found:
            if len(matches(actual_values,new_values))==1:continue
            raise ValueError('Changed Rust structure no longer matches this tranche; no files written')
        if len(found)!=1:raise ValueError('Ambiguous Rust structure near '+repr(old_values[:12])+'; no files written')
        at=found[0]; start=actual[at][1]; end=actual[at+len(old_values)-1][2]
        old_text=before[old[a][1]:old[b-1][2]]
        actual_text=current[start:end]
        if [t[0] for t in tokens(old_text,True)] != [t[0] for t in tokens(actual_text,True)]:
            raise ValueError('A comment changed inside a touched region; preserving it by stopping')
        replacement=after[new[c][1]:new[d-1][2]]
        edits.append((start,end,replacement))
    for start,end,replacement in sorted(edits,reverse=True):current=current[:start]+replacement+current[end:]
    return current

def replace_file(path,data,mode):
    path.parent.mkdir(parents=True,exist_ok=True)
    fd,tmp=tempfile.mkstemp(prefix='.'+path.name+'.catalog-',dir=path.parent)
    try:
        with os.fdopen(fd,'wb') as out:out.write(data);out.flush();os.fsync(out.fileno())
        os.chmod(tmp,mode);os.replace(tmp,path)
    finally:
        if os.path.exists(tmp):os.unlink(tmp)

def prepare(root):
    changes=json.loads(gzip.decompress(base64.b64decode(PAYLOAD)))
    planned=[]
    for item in changes:
        path=root/item['path']
        if path.is_symlink() or any(p.is_symlink() for p in path.parents if p!=root.parent):
            raise ValueError('Refusing symlinked source path: '+str(path))
        original=path.read_bytes() if path.exists() else None
        current=original.decode() if original is not None else None
        if current is not None and values(current)==values(item['after']):continue
        if item['before'] is None:
            if current==item['after']:continue
            if current is not None:raise ValueError('New module already has different authored content: '+str(path))
            updated=item['after']
        else:
            if current is None:raise ValueError('Required migrated source file is missing: '+str(path))
            try:updated=patch_text(current,item['before'],item['after'])
            except ValueError as error:raise ValueError(item['path']+': '+str(error)) from error
        if current==updated:continue
        mode=stat.S_IMODE(path.stat().st_mode) if path.exists() else 0o644
        planned.append((path,original,updated.encode(),mode))
    # Check only this delta. Unrelated pre-existing whitespace defects cannot block it.
    with tempfile.TemporaryDirectory(prefix='vapor-catalog-check-') as tmp:
        for number,(path,old,new,mode) in enumerate(planned):
            a=Path(tmp)/str(number);b=Path(tmp)/(str(number)+'-new')
            a.write_bytes(old or b'');b.write_bytes(new)
            result=subprocess.run(['git','diff','--no-index','--check',str(a),str(b)],capture_output=True,text=True)
            if result.returncode not in (0,1) or result.stdout or result.stderr:
                raise ValueError('Delta whitespace check failed for '+str(path)+'\n'+result.stdout+result.stderr)
    return planned

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root',type=Path,default=Path.home()/'Vapor/Vapor-Client')
    parser.add_argument('--check',action='store_true',help='Preflight without writes')
    args=parser.parse_args();root=args.root.expanduser().resolve()
    if not (root/'Vapor-Studio').is_dir() or not (root/'Vapor/crates/vapor_client_protocol').is_dir():
        raise ValueError('Select the migrated Vapor-Client source root with --root')
    planned=prepare(root)
    if args.check:
        print(f'Preflight passed: {len(planned)} file(s) would change; no writes.');return
    touched=[]
    try:
        for path,old,new,mode in planned:
            # Refuse concurrent changes after preflight, preserving other sessions.
            actual=path.read_bytes() if path.exists() else None
            if actual!=old:raise ValueError('Source changed during installation: '+str(path))
            replace_file(path,new,mode);touched.append((path,old,new,mode))
    except Exception:
        for path,old,new,mode in reversed(touched):
            if path.read_bytes()!=new:
                print('Concurrent edit retained; manual reconciliation required: '+str(path),file=sys.stderr);continue
            if old is None:path.unlink()
            else:replace_file(path,old,mode)
        raise
    print(f'Applied {len(planned)} file(s). Existing staging and unrelated work preserved.')
    print('Code-written only. Rust compilation, tests, runtime and deployment have NOT run.')
    print('No GitHub issue mutation was made; synchronize the checkpoint after validation.')

if __name__=='__main__':
    try:main()
    except Exception as error:
        print('Stopped safely: '+str(error),file=sys.stderr);sys.exit(1)
